import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
db = sqlite3.connect(":memory:", check_same_thread=False)
db.row_factory = sqlite3.Row

@app.before_request
def load_user():                       # stand-in for real login
    g.user_id = int(request.headers.get("X-Test-User", "0"))

@app.get("/invoices/search")
def search_invoices():
    q = request.args.get("q", "")
    rows = db.execute(
        f"SELECT id, title FROM invoices WHERE owner_id = {g.user_id} "
        f"AND title LIKE '%{q}%'"
    ).fetchall()
    return jsonify([dict(r) for r in rows])

@app.get("/invoices/<int:invoice_id>")
def get_invoice(invoice_id):
    row = db.execute("SELECT * FROM invoices WHERE id = ?",
                     (invoice_id,)).fetchone()
    return jsonify(dict(row)) if row else ("not found", 404)

@app.get("/invoices/<int:invoice_id>/note")
def invoice_note(invoice_id):
    row = db.execute("SELECT note FROM invoices WHERE id = ? AND owner_id = ?",
                     (invoice_id, g.user_id)).fetchone()
    if row is None:
        return "not found", 404
    return "<p>Note: " + row["note"] + "</p>"

