import sqlite3
from flask import Flask, request, abort

app = Flask(__name__)
db = sqlite3.connect("shop.db", check_same_thread=False)

@app.get("/search")
def search():
    q = request.args.get("q", "")
    sql = "SELECT id, title FROM items WHERE title LIKE '%" + q + "%'"
    return {"rows": db.execute(sql).fetchall()}

@app.get("/item")
def item():
    item_id = int(request.args.get("id", "0"))
    return {"row": db.execute(f"SELECT * FROM items WHERE id = {item_id}").fetchone()}

@app.get("/sorted")
def sorted_items():
    col = request.args.get("sort", "title")
    if col not in ("title", "price"):
        abort(400)
    return {"rows": db.execute(f"SELECT * FROM items ORDER BY {col}").fetchall()}

@app.get("/safe")
def safe():
    q = request.args.get("q", "")
    sql = "SELECT id, title FROM items WHERE title LIKE ?"
    return {"rows": db.execute(sql, ("%" + q + "%",)).fetchall()}

