import sqlite3
from typing import LiteralString

class SafeDB:
    """The only database API the paved road offers: SQL must be a literal."""
    def __init__(self, path: str) -> None:
        self._conn = sqlite3.connect(path)

    def query(self, sql: LiteralString, params: tuple = ()) -> list:
        return self._conn.execute(sql, params).fetchall()

db = SafeDB(":memory:")

def search(q: str) -> list:
    return db.query("SELECT id FROM items WHERE title LIKE ?", ("%" + q + "%",))  # ok

def search_bad(q: str) -> list:
    return db.query("SELECT id FROM items WHERE title LIKE '%" + q + "%'")       # error

